import json, subprocess, sys

GATE = '/workspace/submission/gateway.py'

def run(batch):
    p = subprocess.run([sys.executable, GATE], input=json.dumps(batch).encode(),
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode != 0:
        raise SystemExit('nonzero exit: %r\n%s' % (p.returncode, p.stderr.decode()[:2000]))
    return json.loads(p.stdout.decode())

def job(raw, gateway='edge', kind='local', subject='s1', peer=None, trusted=True):
    ing = {'kind': kind}
    if kind == 'local':
        ing['subject'] = subject
    elif kind == 'peer':
        ing['name'] = peer
    j = {'gateway': gateway, 'ingress': ing, 'trusted_out': trusted}
    if raw is not None:
        j['raw'] = raw
    return j

def msg(**kw):
    body = kw.pop('body', 'hi')
    d = {'From': '<sip:a@x.test>;tag=t1', 'To': '<sip:b@y.test>', 'Call-ID': 'c1',
         'CSeq': '1 MESSAGE', 'Content-Length': str(len(body))}
    d.update(kw)
    lines = ['MESSAGE sip:b@y.test SIP/2.0']
    for k, v in d.items():
        if v is None:
            continue
        lines.append('%s: %s' % (k, v))
    text = '\r\n'.join(lines) + '\r\n\r\n' + body
    return text

