FAILS = []
def check(name, got, want):
    ok = True
    if isinstance(want, dict) and want.get('status') == 'accept':
        if got.get('status') != 'accept':
            ok = False
        else:
            for k, v in want.items():
                if got.get(k) != v:
                    ok = False
                    break
            if set(got.keys()) != {'status','identity','basis','private','wire'}:
                ok = False
    else:
        ok = got == want
    if not ok:
        FAILS.append(name)
        print('FAIL %-42s got=%s' % (name, json.dumps(got)[:300]))
        if isinstance(want, dict) and 'wire' in want:
            print('      want wire=%r' % want['wire'])
            print('      got  wire=%r' % got.get('wire'))
    else:
        print('ok   %-42s' % name)

def r(reason):
    return {'status': 'reject', 'reason': reason}
